<?php
require __DIR__.'/common.php';
$q=trim($_GET['q']??'');
if($q!==''){$s=$pdo->prepare("SELECT slug,title,description FROM pages WHERE status='published' AND (title LIKE ? OR description LIKE ? OR body LIKE ?) ORDER BY updated_at DESC LIMIT 100");$l='%'.$q.'%';$s->execute([$l,$l,$l]);$pages=$s->fetchAll();}
else {$pages=$pdo->query("SELECT slug,title,description FROM pages WHERE status='published' ORDER BY updated_at DESC LIMIT 50")->fetchAll();}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($config['site_name'])?></title><meta name="description" content="موقع شخصي لنشر الصفحات والمحتوى ومشاركته عبر روابط مستقلة."><link rel="stylesheet" href="assets/style.css"></head><body><header class="top"><strong><?=e($config['site_name'])?></strong><nav><a href="login.php">دخول المدير</a></nav></header><main class="wrap"><section class="hero"><h1>مرحباً بك في <?=e($config['site_name'])?></h1><p>ابحث في الصفحات المنشورة أو افتح الرابط الذي تمت مشاركته معك.</p><form class="search"><input name="q" value="<?=e($q)?>" placeholder="ابحث عن صفحة..."><button>بحث</button></form></section><h2><?=$q?'نتائج البحث':'أحدث الصفحات'?></h2><div class="cards"><?php foreach($pages as $p):?><a class="card" href="page.php?slug=<?=urlencode($p['slug'])?>"><h3><?=e($p['title'])?></h3><p><?=e($p['description'])?></p><span>عرض الصفحة ←</span></a><?php endforeach;?><?php if(!$pages):?><p>لا توجد صفحات منشورة حالياً.</p><?php endif;?></div></main></body></html>
